<?php
declare(strict_types=1);require $argv[1];
$c=json_decode(file_get_contents($argv[2]),true,64,JSON_THROW_ON_ERROR);$method=new ReflectionMethod(HostWebControl::class,'warmSentinel');$requests=0;$started=hrtime(true);
$probe=static function()use($c,&$requests):array{$requests++;$body=file_get_contents($c['origin'].$c['rpc'],false,stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\nX-Ald1n-Release-Front: ".$c['token']."\r\nX-Ald1n-Release-Token: ".$c['token'],'content'=>'{"action":"probe"}','timeout'=>5]]));$r=json_decode($body,true,64,JSON_THROW_ON_ERROR);if(($r['status']??null)!=='ok'||$r['id']!==$c['id']||$r['librarySHA256']!==$c['librarySHA256']||$r['actualIndex']!==true||$r['uid']!==posix_geteuid())throw new RuntimeException('FIXTURE_HTTP_SCOPE');return $r;};
try{$method->invoke(null,$probe);$later=$probe();if(($later['sentinelPreviouslyCached']??false)!==true)throw new RuntimeException('LATER_REQUEST_NOT_CACHED');echo json_encode(['status'=>'warm','requests'=>$requests,'elapsedSeconds'=>(hrtime(true)-$started)/1e9,'laterRequestCached'=>true]).PHP_EOL;exit(0);}catch(Throwable $e){echo json_encode(['status'=>'hold','code'=>$e->getMessage(),'requests'=>$requests,'elapsedSeconds'=>(hrtime(true)-$started)/1e9]).PHP_EOL;exit(2);}
